def index_rows(rows):
    """Create an index mapping each non-null key to a list of its associated values.
    The order of values follows the order they appear in *rows*.
    Null keys are ignored because they never match.
    """
    index = {}
    for row in rows:
        key = row.get("key")
        if key is not None:
            index.setdefault(key, []).append(row["value"])
    return index

